// CheckPermissions operation middleware
func (sh *strictHandler) CheckPermissions(ctx echo.Context) error {
	var request CheckPermissionsRequestObject

	var body CheckPermissionsJSONRequestBody
	if err := ctx.Bind(&body); err != nil {
		return err
	}
	request.Body = &body

	handler := func(ctx echo.Context, request interface{}) (interface{}, error) {
		return sh.ssi.CheckPermissions(ctx.Request().Context(), request.(CheckPermissionsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "CheckPermissions")
	}

	response, err := handler(ctx, request)

	if err != nil {
		return err
	} else if validResponse, ok := response.(CheckPermissionsResponseObject); ok {
		return validResponse.VisitCheckPermissionsResponse(ctx.Response())
	} else if response != nil {
		return fmt.Errorf("unexpected response type: %T", response)
	}
	return nil
}

